using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
public static class MarsRockExport {public static void Export(){string outDir="Assets/MarsEnvironmentRockExport";Directory.CreateDirectory(outDir);foreach(string name in new[]{"rock_07","rock_09"})for(int l=0;l<3;l++){var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/ApprovedAssets/"+name+"_LOD"+l+".glb");if(!source)throw new System.Exception("Approved rock missing");var root=(GameObject)PrefabUtility.InstantiatePrefab(source);var filters=root.GetComponentsInChildren<MeshFilter>();var mesh=new Mesh{name=name+"_LOD"+l};mesh.CombineMeshes(filters.Select(f=>new CombineInstance{mesh=f.sharedMesh,transform=f.transform.localToWorldMatrix}).ToArray(),true,true);var b=mesh.bounds;var v=mesh.vertices;var shift=new Vector3(b.center.x,b.min.y,b.center.z);for(int i=0;i<v.Length;i++)v[i]=(v[i]-shift)/Mathf.Max(b.size.x,Mathf.Max(b.size.y,b.size.z));mesh.vertices=v;mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,outDir+"/"+mesh.name+".asset");Object.DestroyImmediate(root);}AssetDatabase.SaveAssets();Debug.Log("APPROVED_ROCK_NATIVE_EXPORT_PASS");}}
